public enum ColorUtils {
    /// The hue and saturation of a colour temperature in mired (clamped to 100...500), from HAP-NodeJS's lookup
    /// table. Adaptive Lighting sets these on a lightbulb with Hue and Saturation; a plugin that converts with
    /// the same table sends no extra events. Rounded to integers unless `rounded` is false.
    public static func colorTemperatureToHueAndSaturation(_ colorTemperature: Double, rounded: Bool = true) -> (hue: Double, saturation: Double) {
        let mired = Int(min(500, max(100, colorTemperature)).rounded(.toNearestOrAwayFromZero))
        let (saturation, hue) = table[mired - 100]
        return rounded ? (hue.rounded(.toNearestOrAwayFromZero), saturation.rounded(.toNearestOrAwayFromZero)) : (hue, saturation)
    }

